### Important: Supabase Setup

Since this code interacts with Supabase, you must run the following SQL in your Supabase project's SQL Editor to set up the database tables and trigger the user profile creation on signup.

```sql
-- 1. Create Profiles Table (Publicly readable for names)
create table profiles (
  id uuid references auth.users not null primary key,
  username text,
  is_admin boolean default false,
  avatar_url text
);

-- 2. Trigger to create profile on signup
create or replace function public.handle_new_user() 
returns trigger as $$
begin
  insert into public.profiles (id, username)
  values (new.id, new.raw_user_meta_data->>'username');
  return new;
end;
$$ language plpgsql security definer;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- 3. Create Weekly Readings Table
create table weekly_readings (
  id uuid default gen_random_uuid() primary key,
  created_at timestamptz default now(),
  reference text,
  text text,
  version text,
  theme text,
  week_start_date date
);

-- 4. Create Reflections Table
create table reflections (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null,
  reading_id uuid references weekly_readings(id) not null,
  text text,
  acknowledged boolean default false,
  created_at timestamptz default now()
);

-- 5. Set up Row Level Security (RLS) policies
alter table profiles enable row level security;
alter table weekly_readings enable row level security;
alter table reflections enable row level security;

-- Policies (Simplified for demo)
-- Everyone can read profiles
create policy "Public profiles are viewable by everyone." on profiles for select using (true);
-- Users can update own profile
create policy "Users can update own profile." on profiles for update using (auth.uid() = id);

-- Everyone can read readings
create policy "Readings are viewable by everyone." on weekly_readings for select using (true);
-- Only admins can insert readings (You might need to manually set is_admin=true on your user in DB)
create policy "Admins can insert readings." on weekly_readings for insert with check (
  exists ( select 1 from profiles where id = auth.uid() and is_admin = true )
);

-- Everyone can read reflections (for the dashboard/feed)
create policy "Reflections are viewable by everyone." on reflections for select using (true);
-- Users can insert/update own reflections
create policy "Users can insert own reflections." on reflections for insert with check (auth.uid() = user_id);
create policy "Users can update own reflections." on reflections for update using (auth.uid() = user_id);
